import os
import re

from abc import ABC
from typing import Optional

from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper

from taf.rfrl.csv4all.resources.test_cases import UpgradeTest
from taf.rfrl.csv4all.resources.test_cases.exceptions import IterationFailedError, IndependentSwUpdateError
from taf.rfrl.csv4all.resources.node.exceptions import WrongSwVersion, SwDownloadError, SwActivationError
from taf.rfrl.csv4all.resources.node.node import Node
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator, function_wrapper
from taf.rfrl.csv4all.resources.utilities.exceptions import FatalError
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class ParallelUpgradeTest(UpgradeTest, ABC):

    def __init__(self, nodes_details, test_nodes_details, iterations_per_node, report,
                 calculate_kpi: Optional[bool] = True, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain=None, qc_id=None,
                 qc_project=None, customers_list=None,
                 report_comment=None, sw_build=None, topology=None, use_external_storage: Optional[bool] = False,
                 download_path=None,
                 use_testpackage: Optional[bool] = False, stop_test_after_fail: Optional[bool] = False,
                 artifactory_location: Optional[str] = "espoo2", package_suffix: Optional[str] = "A54",
                 l3_call_method=None,
                 synchronize_software_on_passive: Optional[bool] = False, yaft_path: Optional[str] = "/home/ute/YAFT",
                 virtualenv_dir: Optional[str] = None, detailed_console_log: bool = True, ru_update_sw: bool = False,
                 collect_passed_logs: int = 0, diagnostic_check: bool = False):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, use_external_storage, download_path, use_testpackage,
                         stop_test_after_fail, artifactory_location, package_suffix, l3_call_method,
                         synchronize_software_on_passive, yaft_path, virtualenv_dir, detailed_console_log, ru_update_sw,
                         collect_passed_logs=collect_passed_logs, diagnostic_check=diagnostic_check)
        self.failed_nodes = set()
        self._add_fid23_as_temporary_alarm()

    def parallel_test_operation(self):
        self.set_timestamp_reporting_and_kpi()
        self.software_update_test()
        return self.failed_nodes

    @method_decorator()
    def verify_active_sw_on_test_nodes(self, sw):
        for node in self.test_nodes:
            sw_build = getattr(node, sw)
            try:
                node.verify_active_sw_version(sw_build)
            except WrongSwVersion as e:
                raise e

    def software_update_test(self, operation: str = "update"):
        with RobotWrapper("Software Update Test", "kw"):
            self.failed_nodes = self.parallel_update_sw_operation(operation)
            if self.current_iteration == "Iteration_1":
                self.failed_nodes.update(self.validate_all_nodes_scf())
            self.failed_nodes.update(self.perform_dnr_partition_check_on_all_nodes(check_after_upgrade=True))
            self._log_operation_status(operation, self.failed_nodes)

    def parallel_update_sw_operation(self, operation: str = "update"):
        for node in self.test_nodes:
            self.set_target_sw_path(node)
        try:
            self.multi_runner.start_log_tracing_all_nodes()
            self.multi_runner.start_watching_alarms_on_all_nodes()
            self.failed_nodes_during_update = self.parallel_software_precheck()
            self.failed_nodes_during_update.update(self.parallel_diagnostic_check())
            self.parallel_live_update_precheck()
            self.gather_blackbox_and_set_reset_counter(operation)
            if self.calculate_kpi:
                self.kpi.kpi_calc.save_search_start_timestamp()
            self.perform_parallel_sw_update()
            self.failed_nodes_during_update.update(self.verify_nodes_after_parallel_sw_change_operation(operation))
            if not self.failed_nodes_during_update and not self.passed_logs_gathered:
                self.gather_mumin_logs_and_snapshot(operation)
            return self.failed_nodes_during_update
        except Exception as e:
            return self.exception_handling_parallel(operation=operation, exception=e)
        finally:
            self.remove_allowed_alarms_from_nodes(self.nodes, self.all_allowed_specific_faults)
            for node in self.test_nodes:
                node.logsverify.reset_check = True
            if self.calculate_kpi:
                self.collect_infomodel_logs_from_nodes()

    @method_decorator()
    def perform_parallel_sw_update(self):
        self.parallel_independent_sw_update()
        self.perform_multi_node_sw_download()
        self.add_allowing_alarms()
        self.perform_multi_node_sw_activation()

    def perform_multi_node_sw_activation(self):
        activation_results = self.multi_runner.run_operations_as_threads_and_return(self.test_nodes,
                                                                                    Node.activate_sw,
                                                                                    self.current_logs_dir,
                                                                                    self.mplane_access_timeout)
        if activation_results.get("Failed"):
            failed_nodes = [node_alias for node_alias in activation_results["Failed"].keys()]
            test_logger(f"Multi node SW activation failed on: {','.join(failed_nodes)}", "ERROR")
            raise SwActivationError()
        return True

    def perform_multi_node_sw_download(self):
        download_results = self.multi_runner.run_operations_as_threads_and_return(self.test_nodes,
                                                                                  Node.download_sw)
        if download_results.get("Failed"):
            failed_nodes = [node_alias for node_alias in download_results["Failed"].keys()]
            test_logger(f"Multi node SW download failed on: {','.join(failed_nodes)}", "ERROR")
            for node_alias in failed_nodes:
                node = self.node_factory.get_node_by_alias(self.nodes, node_alias)
                if "not completed within timeout" in str(download_results["Failed"][node_alias]):
                    node.wait_till_sw_download_finish()
            raise SwDownloadError()

    def verify_nodes_after_parallel_sw_change_operation(self, operation):
        self.multi_runner.execute_commands_on_rmods()
        failed_nodes_during_operation = self.multi_runner.verify_all_nodes()
        failed_nodes_during_operation.update(self.multi_runner.stop_logs_and_verify_on_all_nodes(
            f"{self.current_logs_dir}/{operation}",
            None, self.reset_incrementation))
        failed_nodes_during_operation.update(self.check_rmod_blackbox_parallel())
        return failed_nodes_during_operation

    def test(self):
        self.run_iteration_precondition()
        self._set_current_logs_dir(None)
        self.failed_nodes = self.parallel_test_operation()
        self.report_results_to_uuf_dashboard()
        if self.failed_nodes:
            raise IterationFailedError(f"Iteration Failed. Issues detected on nodes : {self.failed_nodes}")
        else:
            test_logger(f"Iteration No. {self.current_iteration.split('_')[1]} Passed", hyperlink=True)
        if self.l3_call_method and not self.l3_call_result:
            raise IterationFailedError("Iteration Failed. L3 Call failed.")

    def test_teardown(self):
        self.current_logs_dir = f"{self.log_dir}/Test_Teardown"
        super().test_teardown()

    def test_operation(self, node):
        pass

    @method_decorator()
    def collect_infomodel_logs_from_nodes(self):
        if self.calculate_kpi:
            self.kpi.kpi_calc.save_search_end_timestamp()
        for node in self.test_nodes:
            if self.calculate_kpi:
                self.collect_infomodel_log(node)

    @method_decorator()
    def collect_infomodel_log(self, node):
        node.admin.collect_infomodel_log_from_current_session(target_file_name=f"{self.current_logs_dir}/"
                                                                               f"oam_kpis/{node.node_alias}/update/"
                                                                               f"OAM_KPI_{node.node_alias}_2.ims2")

    def exception_handling_parallel(self, operation: str, exception):
        test_logger(f"{operation.upper()} FAILED", 'error')
        test_logger(exception, console=False)
        for node in self.test_nodes:
            if self.report_to_rp:
                self.test_reporter.report_result_to_uuf_dashboard(node, "failed",
                                                                  self.kpi.get_uuf_kpi(self.uuf_case_type),
                                                                  self.current_iteration)
        try:
            self.gather_mumin_logs_and_snapshot(operation)
            return {node.node_alias for node in self.test_nodes}
        except Exception as operation_error:
            (operation_error,) = operation_error.args
            regexp = re.search("(?<=Failed nodes: )(.*)", str(operation_error))
            if regexp:
                return eval(regexp.group(0))
            return {node.node_alias for node in self.test_nodes}

    @staticmethod
    def _check_if_paths_are_similar(node):
        return "_".join(node.target_sw.split("_")[:-1]) == "_".join(node.source_sw.split("_")[:-1])

    @method_decorator()
    def synchronize_software_on_passive_on_test_nodes(self, test_nodes: list = None):
        nodes = test_nodes or self.test_nodes
        synchronize_results = \
            self.multi_runner.run_operations_as_threads_and_return(nodes,
                                                                   Node.synchronize_software_on_passive)
        if synchronize_results["Failed"]:
            failed_nodes = {node for node in {*synchronize_results['Failed'].keys()}}
            test_logger(f"Synchronizing software to passive failed on nodes: {failed_nodes}", "ERROR")

    @method_decorator()
    def perform_live_update_check_on_test_nodes(self):
        live_update_results = \
            self.multi_runner.run_operations_as_threads_and_return(self.test_nodes,
                                                                   Node.perform_live_update_check)
        make_synchronize_nodes = []
        for node in self.test_nodes:
            if node.live_update:
                make_synchronize_nodes.append(node)
                node.logsverify.reset_check = False
                self.calculate_kpi = False
        if make_synchronize_nodes:
            test_logger("Small Update will be performed. Calculating KPI will be disabled", "WARN")
            if not self.synchronize_software_on_passive:
                self.synchronize_software_on_passive_on_test_nodes(make_synchronize_nodes)
        if live_update_results["Failed"]:
            failed_nodes = {node for node in {*live_update_results['Failed'].keys()}}
            test_logger(f"Small update check failed on nodes: {','.join(failed_nodes)}", "ERROR")

    @method_decorator()
    def validate_all_nodes_scf(self):
        validate_results = \
            self.multi_runner.run_operations_as_threads_and_return(self.test_nodes, Node.validate_current_scf,
                                                                   self.current_logs_dir)
        failed_nodes = {node for node in {*validate_results['Failed'].keys()}}
        if validate_results["Failed"]:
            test_logger(f"Validation scf failed on nodes: {','.join(failed_nodes)}", "ERROR")
        return failed_nodes

    @method_decorator()
    def perform_dnr_partition_check_on_all_nodes(self, check_after_upgrade: bool = False):
        failed_nodes = set()
        for node in self.test_nodes:
            if node.ssh_manager.get_module_type() not in ("FSMF", "FSIH"):
                failed_nodes.update(self.perform_dnr_partition_check(node, check_after_upgrade))
        return failed_nodes

    @method_decorator()
    def run_kpi_calculation(self, node):
        self._set_current_logs_dir(None)
        try:
            test_logger("Calculating OAM KPI")
            self.select_upgrade_kpi(node)
            self.kpi.kpi_calc.serial_console_connected = len(node.btsverify.cells_verifier.serial_console_cells) > 0
            self.kpi.set_end_timestamp_for_kpi_calculation()
            self.kpi.calculate_proper_oam_kpi(f"{self.current_logs_dir}/oam_kpis/{node.node_alias}/update/")
        except Exception as e:
            test_logger(e, console=False)
            test_logger("KPI Calculation failed", "ERROR")
        finally:
            if self.report_to_rp:
                result = "failed" if self.failed_nodes or self.precheck_failed else "passed"
                self.test_reporter.report_result_to_uuf_dashboard(node, result,
                                                                  self.kpi.get_uuf_kpi(self.uuf_case_type),
                                                                  self.current_iteration)

    def _set_current_logs_dir(self, node):
        self.current_logs_dir = os.path.join(self.log_dir, self.current_iteration)

    @function_wrapper
    def add_allowing_alarms(self):
        for node in self.test_nodes:
            test_logger(f"Adding allowed faults: {', '.join(self.all_allowed_specific_faults)} for {node.node_alias}",
                        console=False)
            self.add_test_specific_alarm(node)

    @method_decorator()
    def add_test_specific_alarm(self, node):
        for fault_id in self.all_allowed_specific_faults:
            node.add_test_specific_alarm(fault_id=fault_id)

    def _log_operation_status(self, operation: str, failed_nodes: set):
        if failed_nodes:
            test_logger(f"Given nodes failed during {operation.upper()} {','.join(failed_nodes)}", "ERROR")
            self.gather_mumin_logs_and_snapshot(operation)
            if self.stop_test_after_fail:
                raise FatalError(f"Test has been stopped, stop_test_after_fail is True")
        for node in self.test_nodes:
            if node.node_alias in failed_nodes:
                test_logger(f"[{node.node_alias}] {operation.upper()} FAILED", hyperlink=True)
            else:
                test_logger(f"[{node.node_alias}] {operation.upper()} PASSED", hyperlink=True)

    @method_decorator()
    def parallel_independent_sw_update(self):
        if self.ru_update_sw:
            ru_update_results = \
                self.multi_runner.run_operations_as_threads_and_return(self.test_nodes,
                                                                       Node.independent_du_update_sw)
            if ru_update_results["Failed"]:
                failed_nodes = {node for node in {*ru_update_results['Failed'].keys()}}
                test_logger(f"Independent SW Update failed on nodes: {','.join(failed_nodes)}", "ERROR")
                raise IndependentSwUpdateError()
            if self.calculate_kpi:
                self.kpi.set_start_timestamp_for_kpi_calculation()

    @method_decorator()
    def parallel_live_update_precheck(self):
        if self.synchronize_software_on_passive:
            self.synchronize_software_on_passive_on_test_nodes()
        self.perform_live_update_check_on_test_nodes()

    def _add_fid23_as_temporary_alarm(self):
        for node in self.test_nodes:
            node.add_temporary_alarm("23")

    @method_decorator()
    def parallel_software_precheck(self):
        software_precheck_results = \
            self.multi_runner.run_operations_as_threads_and_return(self.test_nodes, Node.perform_software_precheck)
        if software_precheck_results["Failed"]:
            failed_nodes = {node for node in {*software_precheck_results['Failed'].keys()}}
            for node, exception in software_precheck_results["Failed"].items():
                if hasattr(exception, "exception"):
                    test_logger(exception.exception, "ERROR")
                    break
            test_logger(f"Software precheck failed on nodes: {','.join(failed_nodes)}", "ERROR")
            self.gather_mumin_logs_and_snapshot("software_precheck")
            return failed_nodes
        test_logger("Software precheck passed")
        return set()

    @method_decorator()
    def parallel_diagnostic_check(self):
        if self.diagnostic_check:
            diagnostic_check_results = \
                self.multi_runner.run_operations_as_threads_and_return(self.test_nodes, Node.perform_diagnostic_check,
                                                                       self.current_logs_dir)
            if diagnostic_check_results["Failed"]:
                failed_nodes = {node for node in {*diagnostic_check_results['Failed'].keys()}}
                for node, exception in diagnostic_check_results["Failed"].items():
                    if hasattr(exception, "exception"):
                        test_logger(exception.exception, "ERROR")
                        break
                test_logger(f"Diagnostic check failed on nodes: {','.join(failed_nodes)}", "ERROR")
                self.gather_mumin_logs_and_snapshot("diagnostic_check")
                return failed_nodes
            test_logger("Diagnostic check passed")
        return set()

    def check_rmod_blackbox_parallel(self):
        ru_blackbox_results = \
            self.multi_runner.run_operations_as_threads_and_return(self.test_nodes, Node.verify_ru_blackbox,
                                                                   f"{self.current_logs_dir}/rmods_blackbox")
        if ru_blackbox_results["Failed"]:
            failed_nodes = {node for node in {*ru_blackbox_results['Failed'].keys()}}
            for node, exception in ru_blackbox_results["Failed"].items():
                if hasattr(exception, "exception"):
                    test_logger(exception.exception, "ERROR")
                    break
            test_logger(f"RU Blackbox verificationfailed on nodes: {','.join(failed_nodes)}", "ERROR")
            self.gather_mumin_logs_and_snapshot("ru_blackbox")
            return failed_nodes
        test_logger("RU Blackbox verification passed")
        return set()
